class Solution {
    static int sumDigits(int n) {
        int sum = 0;
        while (n > 0) {
            sum += n % 10;
            n /= 10;
        }
        return sum;
    }
}

class Solution {
    static int countThrees(int n) {
        int count = 0;
        while (n > 0) {
            if (n % 10 == 3) count++;
            n /= 10;
        }
        return count;
    }
}

class Solution {
    static boolean isPrime(int n) {
        if (n < 2) return false;
        for (int i = 2; i <= n / i; i++) {
            if (n % i == 0) return false;
        }
        return true;
    }
}

class Solution {
    static int firstMaxIndex(int[] a) {
        if (a == null || a.length == 0)
            throw new IllegalArgumentException("Vector gol");
        int best = 0;
        for (int i = 1; i < a.length; i++) {
            if (a[i] > a[best]) best = i;
        }
        return best;
    }
}

class Solution {
    static void reverse(int[] a) {
        int left = 0, right = a.length - 1;
        while (left < right) {
            int tmp = a[left];
            a[left] = a[right];
            a[right] = tmp;
            left++;
            right--;
        }
    }
}

class Solution {
    static int binarySearch(int[] a, int target) {
        int left = 0, right = a.length - 1;
        while (left <= right) {
            int mid = left + (right - left) / 2;
            if (a[mid] == target) return mid;
            if (a[mid] < target) left = mid + 1;
            else right = mid - 1;
        }
        return -1;
    }
}

class Solution {
    static long factorial(int n) {
        if (n < 0 || n > 20)
            throw new IllegalArgumentException("n trebuie sa fie 0..20");
        if (n <= 1) return 1L;
        return n * factorial(n - 1);
    }
}

class Solution {
    static long sum(int[] a) {
        return sumFrom(a, 0);
    }
    private static long sumFrom(int[] a, int i) {
        if (i == a.length) return 0L;
        return a[i] + sumFrom(a, i + 1);
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}
class Solution {
    static int countNodes(TreeNode root) {
        if (root == null) return 0;
        return 1 + countNodes(root.left)
                 + countNodes(root.right);
    }
}

class TreeNode {
    int val;
    TreeNode left, right;
    TreeNode(int val) { this.val = val; }
}
class Solution {
    static int height(TreeNode root) {
        if (root == null) return 0;
        return 1 + Math.max(height(root.left),
                            height(root.right));
    }
}
